export const getVendorTaxEstimateUrl = (id: string, params: VendorTaxEstimateParams) => {
  const normalizedParams = new URLSearchParams()

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : String(value))
    }
  })

  const stringifiedParams = normalizedParams.toString()

  return stringifiedParams.length > 0
    ? `${env.API_BASE_URL}/api/v1/vendors/${id}/tax-estimate?${stringifiedParams}`
    : `${env.API_BASE_URL}/api/v1/vendors/${id}/tax-estimate`
}

/**
 * @summary Estimate the tax on a price before tax
 */
export const vendorTaxEstimate = async (
  id: string,
  params: VendorTaxEstimateParams,
  options?: RequestInit
): Promise<vendorTaxEstimateResponseSuccess> => {
  const res = await fetch(getVendorTaxEstimateUrl(id, params), {
    ...options,
    method: 'GET'
  })

  const body = [204, 205, 304].includes(res.status) ? null : await res.text()
  if (!res.ok) {
    const err: globalThis.Error & { info?: vendorTaxEstimateResponseError['data']; status?: number } =
      new globalThis.Error()
    const data: vendorTaxEstimateResponseError['data'] = body ? JSON.parse(body) : {}
    err.info = data
    err.status = res.status
    throw err
  }
  const data: vendorTaxEstimateResponseSuccess['data'] = body ? JSON.parse(body) : {}
  return { data, status: res.status, headers: res.headers } as vendorTaxEstimateResponseSuccess
}

